/**
	* Better Auth — browser client.
	*
	* Use in client components for sign-in / sign-up / magic link / wallet:
	*
	*   const { data, error } = await authClient.signIn.magicLink({
	*     email, callbackURL: "/dashboard",
	*   });
	*   const challenge = await authClient.siwe.nonce({});
	*   // Sign a SIWE message containing challenge.data.nonce, then verify it:
	*   await authClient.siwe.verify({ message, signature });
	*   await authClient.signOut();
	*
	* The plugin surface is generated by `createAuthClient`; the calls match
	* Better Auth's React docs (https://better-auth.com/docs).
	*
	* baseURL is resolved at runtime:
	*   - Same-origin relative (default): uses the /api/auth/* proxy at
	*     app/src/app/api/auth/[...path]/route.ts. Recommended for production.
	*     Cookies are issued by the browser to the public host (oma-ai.com)
	*     and flow correctly between frontend and backend.
	*   - SSR: NEXT_PUBLIC_AUTH_BASE_URL or NEXT_PUBLIC_API_URL selects the
	*     backend directly. Browser requests still use the same-origin proxy.
	*/
import { createAuthClient } from "better-auth/react";
import {
	magicLinkClient,
	siweClient,
} from "better-auth/client/plugins";

function resolveBaseUrl(): string {
	// Browser — use the same-origin /api/auth/* proxy so cookies are
	// stored against the frontend host without cross-origin fetches.
	if (typeof window !== "undefined") {
		return `${window.location.origin}/api/auth`;
	}
	// SSR — call the backend's /api/auth/* directly (same path the
	// same-origin proxy forwards to). The backend serves auth under
	// /api/auth, so the suffix must be appended or every call 404s.
	const envBase =
		process.env.NEXT_PUBLIC_AUTH_BASE_URL ??
		process.env.NEXT_PUBLIC_API_URL ??
		"http://localhost:3001";
	return `${envBase.replace(/\/$/, "")}/api/auth`;
}

export const authClient = createAuthClient({
	baseURL: resolveBaseUrl(),
	// A stalled auth service must release the sign-in form for an explicit retry.
	fetchOptions: {
		timeout: 15_000,
		retry: 0,
		onRequest(context) {
			// BetterFetch's timeout stops at headers and is disabled when a caller
			// supplies a signal. Keep a deadline through body parsing in both cases.
			const deadline = AbortSignal.timeout(context.timeout ?? 15_000);
			context.signal = context.signal ? AbortSignal.any([context.signal, deadline]) : deadline;
			return context;
		},
	},
	plugins: [magicLinkClient(), siweClient()],
});

export const { signIn, signOut: rawSignOut, useSession } = authClient;

export interface SignOutOptions {
	callbackURL?: string;
	disableRedirect?: boolean;
	fetchOptions?: {
		onSuccess?: () => void | Promise<void>;
	};
	[key: string]: unknown;
}

function clearDemoSessionCookie(): void {
	if (typeof document === "undefined") return;
	const suffix = document.location.protocol === "https:" ? "; Secure" : "";
	document.cookie = `oma-demo-public=; Max-Age=0; Path=/; SameSite=Lax${suffix}`;
}

export async function signOut(options: SignOutOptions = {}): Promise<void> {
	const { callbackURL, disableRedirect, ...requestOptions } = options;
	const result = await rawSignOut(requestOptions as Parameters<typeof rawSignOut>[0]);
	if (result.error) {
		throw new Error(result.error.message ?? "Failed to sign out");
	}
	clearDemoSessionCookie();
	if (callbackURL && !disableRedirect && typeof window !== "undefined") {
		const destination = new URL(callbackURL, window.location.origin);
		if (destination.origin === window.location.origin) {
			window.location.assign(`${destination.pathname}${destination.search}${destination.hash}`);
		}
	}
}
